// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IOracleRegistry } from "./interfaces/IOracleRegistry.sol";
import { IPyth } from "./pyth/IPyth.sol";
import { ISwapper } from "./interfaces/ISwapper.sol";

import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SilentERC20 } from "./token/SilentERC20.sol";

contract Swapper is ISwapper, SilentERC20 {
    using SafeERC20 for IERC20;

    uint24 public constant DENOMINATION = 1_000_000;
    IOracleRegistry public immutable ORACLE_REGISTRY;
    IPyth public immutable PYTH;

    constructor(
        string memory name,
        string memory symbol,
        address registry,
        address pyth
    ) SilentERC20(name, symbol) {
        ORACLE_REGISTRY = IOracleRegistry(registry);
        PYTH = IPyth(pyth);
    }

    function getOracleUpdateFee(bytes[] calldata priceUpdate) external view returns (uint256) {
        return PYTH.getUpdateFee(priceUpdate);
    }

    function swapToPrivateToken(SwapParams calldata swapParams) external {}
    function swapFromPrivateToken(SwapParams calldata swapParams) external {}
}

